/**
 * Ad Pack benchmark — 30 FICTIONAL brands/offers across 12 categories.
 * Spanish-first (Costa Rica / LatAm: colones, SINPE Móvil, envíos por Correos/mensajería).
 * Some facts are intentionally unconfirmed and some gaps are left open, to test
 * that the engine never turns them into claims. Any resemblance to real
 * companies is unintended.
 */
import type { AdLanguage, BrandDna, BusinessCategory, DnaFact, FactKey, FactSource, OfferInput } from '../../../api/lib/adpack/types'

export interface BenchmarkCase {
  id: string
  dna: BrandDna
  offer: OfferInput
}

const f = (key: FactKey, value: string, confirmed = true, source: FactSource = 'website'): DnaFact => ({ key, value, source, confirmed })
const o = (key: FactKey, value: string, confirmed = true): DnaFact => ({ key, value, source: 'offer_form', confirmed })

interface CaseSpec {
  id: string
  brandName: string
  category: BusinessCategory
  language?: AdLanguage
  register?: BrandDna['register']
  oneLiner?: string
  voice?: string
  audience?: string[]
  pains?: string[]
  desires?: string[]
  objections?: string[]
  customerPhrases?: string[]
  forbiddenPhrases?: string[]
  facts: DnaFact[]
  gaps?: FactKey[]
  primaryColor?: string
  offerName: string
  offerFacts?: DnaFact[]
}

function mk(s: CaseSpec): BenchmarkCase {
  return {
    id: s.id,
    dna: {
      version: 1,
      brandName: s.brandName,
      category: s.category,
      language: s.language ?? 'es',
      register: s.register ?? 'voseo',
      oneLiner: s.oneLiner,
      voice: s.voice,
      audience: s.audience ?? [],
      pains: s.pains ?? [],
      desires: s.desires ?? [],
      objections: s.objections ?? [],
      customerPhrases: s.customerPhrases ?? [],
      forbiddenPhrases: s.forbiddenPhrases ?? [],
      facts: s.facts,
      visual: { primaryColor: s.primaryColor ?? '#1F6F5C', headingFont: 'Inter', bodyFont: 'Inter' },
      gaps: s.gaps ?? [],
      sources: [{ kind: 'website', url: `https://example.test/${s.id}`, fetchedAt: '2026-10-01T00:00:00Z', ok: true }],
    },
    offer: {
      name: s.offerName,
      facts: s.offerFacts ?? [],
      productImageUrls: [],
    },
  }
}

